import { test, expect } from '@playwright/test';

test.describe('Save Card Details for Future Purchases', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/checkout');
    // Wait for page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display save card option during checkout', async () => {
    // Navigate to payment section
    const paymentSection = page.getByRole('heading', { name: /payment method/i });
    await expect(paymentSection).toBeVisible();

    // Verify card input fields are present
    const cardNumberInput = page.getByLabel(/card number/i);
    await expect(cardNumberInput).toBeVisible();

    const expiryInput = page.getByLabel(/expiry/i);
    await expect(expiryInput).toBeVisible();

    const cvvInput = page.getByLabel(/cvv|security code/i);
    await expect(cvvInput).toBeVisible();

    // Verify save card checkbox is present
    const saveCardCheckbox = page.getByRole('checkbox', { name: /save this card/i });
    await expect(saveCardCheckbox).toBeVisible();
  });

  test('should save card details when checkbox is checked', async () => {
    // Fill in card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4532015112830366');

    const expiryInput = page.getByLabel(/expiry/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|security code/i);
    await cvvInput.fill('123');

    const cardholderInput = page.getByLabel(/cardholder name/i);
    await cardholderInput.fill('John Doe');

    // Check the save card checkbox
    const saveCardCheckbox = page.getByRole('checkbox', { name: /save this card/i });
    await saveCardCheckbox.check();
    await expect(saveCardCheckbox).toBeChecked();

    // Complete the purchase
    const completeButton = page.getByRole('button', { name: /complete purchase|pay now/i });
    await completeButton.click();

    // Wait for success message
    const successMessage = page.getByText(/payment successful|order confirmed/i);
    await expect(successMessage).toBeVisible();
  });

  test('should not save card details when checkbox is unchecked', async () => {
    // Fill in card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4532015112830366');

    const expiryInput = page.getByLabel(/expiry/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|security code/i);
    await cvvInput.fill('123');

    const cardholderInput = page.getByLabel(/cardholder name/i);
    await cardholderInput.fill('Jane Smith');

    // Ensure save card checkbox is unchecked
    const saveCardCheckbox = page.getByRole('checkbox', { name: /save this card/i });
    await saveCardCheckbox.uncheck();
    await expect(saveCardCheckbox).not.toBeChecked();

    // Complete the purchase
    const completeButton = page.getByRole('button', { name: /complete purchase|pay now/i });
    await completeButton.click();

    // Wait for success message
    const successMessage = page.getByText(/payment successful|order confirmed/i);
    await expect(successMessage).toBeVisible();
  });

  test('should display saved cards on future checkout', async () => {
    // First, save a card
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4532015112830366');

    const expiryInput = page.getByLabel(/expiry/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|security code/i);
    await cvvInput.fill('123');

    const cardholderInput = page.getByLabel(/cardholder name/i);
    await cardholderInput.fill('John Doe');

    const saveCardCheckbox = page.getByRole('checkbox', { name: /save this card/i });
    await saveCardCheckbox.check();

    const completeButton = page.getByRole('button', { name: /complete purchase|pay now/i });
    await completeButton.click();

    // Wait for success
    await page.waitForURL(/.*success|confirmation.*/);

    // Navigate to new checkout
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');

    // Verify saved card is displayed
    const savedCardOption = page.getByText(/saved card|use saved card/i);
    await expect(savedCardOption).toBeVisible();

    // Verify card ending in last 4 digits is shown
    const cardDisplay = page.getByText(/ending in 0366|•••• 0366/i);
    await expect(cardDisplay).toBeVisible();
  });

  test('should allow user to select and use a saved card', async () => {
    // Assume a card is already saved from previous test
    // Look for saved card option
    const savedCardRadio = page.getByRole('radio', { name: /saved card|use saved card/i });

    if (await savedCardRadio.isVisible()) {
      await savedCardRadio.click();
      await expect(savedCardRadio).toBeChecked();

      // Verify CVV field appears for saved card
      const cvvInput = page.getByLabel(/cvv|security code/i);
      await expect(cvvInput).toBeVisible();

      // Fill only CVV for saved card
      await cvvInput.fill('123');

      // Complete purchase
      const completeButton = page.getByRole('button', { name: /complete purchase|pay now/i });
      await completeButton.click();

      // Verify success
      const successMessage = page.getByText(/payment successful|order confirmed/i);
      await expect(successMessage).toBeVisible();
    }
  });

  test('should validate required fields before saving card', async () => {
    // Try to save without filling required fields
    const saveCardCheckbox = page.getByRole('checkbox', { name: /save this card/i });
    await saveCardCheckbox.check();

    // Try to complete without filling card details
    const completeButton = page.getByRole('button', { name: /complete purchase|pay now/i });
    await completeButton.click();

    // Verify validation error appears
    const errorMessage = page.getByText(/required|please enter|invalid/i).first();
    await expect(errorMessage).toBeVisible();
  });
});
